CREATE TABLE projects(project_id text PRIMARY KEY, repository_url text NOT NULL);
CREATE TABLE examinations(examination_id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects, title text NOT NULL, external_identifiers jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE targets(target_id text PRIMARY KEY, examination_id text NOT NULL REFERENCES examinations ON DELETE CASCADE, thread text NOT NULL CHECK(thread IN ('root_cause','manifestation')), schema_version text NOT NULL, strategy text NOT NULL, project_id text NOT NULL REFERENCES projects, anchor_revision text NOT NULL, source_payload jsonb NOT NULL, reviewer_status text NOT NULL DEFAULT 'pending' CHECK(reviewer_status IN ('pending','accepted','rejected')));
CREATE TABLE artifacts(artifact_id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects, revision text NOT NULL, role text NOT NULL, artifact_type text NOT NULL, file_path text, function_name text, start_line integer, end_line integer, source text, report_id text, source_uri text, media_type text NOT NULL, content text NOT NULL);
CREATE TABLE target_artifacts(target_id text NOT NULL REFERENCES targets ON DELETE CASCADE, artifact_id text NOT NULL REFERENCES artifacts, role text NOT NULL, revision text NOT NULL, ordinal integer NOT NULL, PRIMARY KEY(target_id,ordinal));
CREATE TABLE target_reviews(target_id text PRIMARY KEY REFERENCES targets ON DELETE CASCADE, status text NOT NULL CHECK(status IN ('pending','accepted','rejected')), reviewer_id text NOT NULL, note text, updated_at timestamptz NOT NULL DEFAULT now());




